BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;
SET LOCAL search_path=public,extensions;
SELECT no_plan();
UPDATE booking_confirmation_control SET enabled=true;
INSERT INTO auth.users(id,email) VALUES ('00000000-0000-4000-a090-000000000001','booking-notices@example.test');
INSERT INTO businesses(id,owner_id,name,business_type,slug,billing_mode,partner_plan,primary_goal) VALUES
 ('10000000-0000-4000-a090-000000000001','00000000-0000-4000-a090-000000000001','Booking','general','booking-090','comped','full','book');
INSERT INTO ai_settings(business_id,booking_enabled,booking_mode) VALUES('10000000-0000-4000-a090-000000000001',true,'schedule_direct') ON CONFLICT(business_id) DO UPDATE SET booking_enabled=true,booking_mode='schedule_direct';
INSERT INTO phone_numbers(business_id,phone_number,telnyx_phone_number_id,is_active) VALUES('10000000-0000-4000-a090-000000000001','+15555550900','booking-090',true);
INSERT INTO contacts(id,business_id,phone_number,source_channel) VALUES('20000000-0000-4000-a090-000000000001','10000000-0000-4000-a090-000000000001','+15555550901','sms');
INSERT INTO conversations(id,business_id,contact_id,channel) VALUES('30000000-0000-4000-a090-000000000001','10000000-0000-4000-a090-000000000001','20000000-0000-4000-a090-000000000001','sms');
INSERT INTO messages(id,business_id,conversation_id,role,channel,content,created_at) VALUES('40000000-0000-4000-a090-000000000001','10000000-0000-4000-a090-000000000001','30000000-0000-4000-a090-000000000001','customer','sms','A callback please',now()-interval '1 second');
CREATE TEMP TABLE drafts AS SELECT (prepare_booking_draft('10000000-0000-4000-a090-000000000001','30000000-0000-4000-a090-000000000001','20000000-0000-4000-a090-000000000001','40000000-0000-4000-a090-000000000001',NULL,'{"offering":{"settingsRevision":0},"mode":"schedule_direct"}','Review details?')).*;
SELECT ok(NOT has_function_privilege('authenticated','public.claim_booking_summary_send(uuid,uuid,integer,text,text,text)','EXECUTE'),'caller cannot manufacture summary acceptance');
SELECT throws_ok($$SELECT claim_booking_summary_send('10000000-0000-4000-a090-000000000001',(SELECT id FROM drafts),1,'+15555550900','+15555550999','Review details?')$$,'P0001','booking summary phone mismatch','summary cannot redirect to another number');
SELECT is((claim_booking_summary_send('10000000-0000-4000-a090-000000000001',(SELECT id FROM drafts),1,'+15555550900','+15555550901','Review details?')->>'send')::boolean,true,'first summary owns submission');
SELECT is((claim_booking_summary_send('10000000-0000-4000-a090-000000000001',(SELECT id FROM drafts),1,'+15555550900','+15555550901','Review details?')->>'send')::boolean,false,'retry cannot submit another summary');
SELECT throws_ok($$SELECT finalize_booking_summary_send((SELECT id FROM drafts))$$,'P0001','booking summary acceptance missing','unknown provider result cannot activate approval');
UPDATE booking_summary_sends SET status='accepted',provider_message_id='summary090',accepted_at=now()+interval '1 second' WHERE draft_id=(SELECT id FROM drafts);
SELECT lives_ok($$SELECT finalize_booking_summary_send((SELECT id FROM drafts))$$,'accepted summary finalized');
SELECT lives_ok($$SELECT finalize_booking_summary_send((SELECT id FROM drafts))$$,'summary finalization repeat is safe');
SELECT is((SELECT count(*)::integer FROM messages WHERE id=(SELECT id FROM drafts)),1,'one outbound summary');
SELECT is((SELECT summary_accepted_at FROM booking_drafts WHERE id=(SELECT id FROM drafts)),now()+interval '1 second','original provider acceptance retained');
SELECT throws_ok($$UPDATE booking_summary_sends SET destination='+15555550999'$$,'P0001','booking summary scope mismatch','summary recipient cannot move');
SELECT throws_ok($$UPDATE booking_summary_sends SET provider_message_id='replacement'$$,'P0001','booking acceptance immutable','provider evidence immutable');
-- Chat recovery uses the committed summary time, not a later maintenance time.
INSERT INTO conversations(id,business_id,contact_id,channel) VALUES('30000000-0000-4000-a090-000000000002','10000000-0000-4000-a090-000000000001','20000000-0000-4000-a090-000000000001','web_chat');
INSERT INTO messages(id,business_id,conversation_id,role,channel,content) VALUES('40000000-0000-4000-a090-000000000002','10000000-0000-4000-a090-000000000001','30000000-0000-4000-a090-000000000002','customer','web_chat','Book please');
CREATE TEMP TABLE chats AS SELECT (prepare_booking_draft('10000000-0000-4000-a090-000000000001','30000000-0000-4000-a090-000000000002','20000000-0000-4000-a090-000000000001','40000000-0000-4000-a090-000000000002',NULL,'{"offering":{"settingsRevision":0},"mode":"schedule_direct"}','Chat review?')).*;
INSERT INTO messages(business_id,conversation_id,role,channel,content,created_at) VALUES('10000000-0000-4000-a090-000000000001','30000000-0000-4000-a090-000000000002','assistant','web_chat','Chat review?',now()+interval '2 seconds');
SELECT ok(recover_booking_chat_summary('10000000-0000-4000-a090-000000000001','30000000-0000-4000-a090-000000000002'),'committed chat summary recovered');
SELECT is((SELECT summary_accepted_at FROM booking_drafts WHERE id=(SELECT id FROM chats)),now()+interval '2 seconds','chat recovery preserves original summary time');
-- Final voice notification may finish after an authorized call hangs up.
INSERT INTO conversations(id,business_id,contact_id,channel) VALUES('30000000-0000-4000-a090-000000000003','10000000-0000-4000-a090-000000000001','20000000-0000-4000-a090-000000000001','voice');
INSERT INTO voice_sessions(id,business_id,conversation_id,action_conversation_id,action_business_id,call_control_id,call_session_id,caller_phone,called_phone,response_mode,status) VALUES('50000000-0000-4000-a090-000000000001','10000000-0000-4000-a090-000000000001','30000000-0000-4000-a090-000000000003','30000000-0000-4000-a090-000000000003','10000000-0000-4000-a090-000000000001','booking090','booking090','+15555550901','+15555550900','voice','closed');
INSERT INTO messages(id,business_id,conversation_id,role,channel,content) VALUES('40000000-0000-4000-a090-000000000003','10000000-0000-4000-a090-000000000001','30000000-0000-4000-a090-000000000003','customer','voice','Yes text it');
INSERT INTO booking_drafts(id,business_id,conversation_id,contact_id,revision,status,snapshot,source_message_id,summary_text) VALUES('60000000-0000-4000-a090-000000000001','10000000-0000-4000-a090-000000000001','30000000-0000-4000-a090-000000000003','20000000-0000-4000-a090-000000000001',1,'confirmed','{}','40000000-0000-4000-a090-000000000003','Voice details');
INSERT INTO voice_actions(id,session_id,business_id,kind,fingerprint,revision,status,payload,readback,request_event_ids,confirmed_at,source_message_id) VALUES('70000000-0000-4000-a090-000000000001','50000000-0000-4000-a090-000000000001','10000000-0000-4000-a090-000000000001','booking_confirmation_text',repeat('a',64),1,'executing','{"kind":"booking_confirmation_text","draftId":"60000000-0000-4000-a090-000000000001","revision":1}','May I text it?',ARRAY['request'],now(),'40000000-0000-4000-a090-000000000003');
INSERT INTO voice_actions(session_id,business_id,kind,fingerprint,revision,status,payload,readback,request_event_ids) VALUES('50000000-0000-4000-a090-000000000001','10000000-0000-4000-a090-000000000001','signup',repeat('b',64),2,'superseded','{}','Legacy signup',ARRAY['request']);
SELECT throws_ok($$INSERT INTO voice_actions(session_id,business_id,kind,fingerprint,revision,status,payload,readback,request_event_ids) VALUES('50000000-0000-4000-a090-000000000001','10000000-0000-4000-a090-000000000001','signup',repeat('b',64),3,'superseded','{}','Legacy signup',ARRAY['request'])$$,'23505',NULL,'signup fingerprints remain unique even when superseded');
SELECT lives_ok($$SELECT authorize_booking_notification('70000000-0000-4000-a090-000000000001','Confirmed details')$$,'authorized final notification survives hangup');
SELECT lives_ok($$SELECT authorize_booking_notification('70000000-0000-4000-a090-000000000001','Confirmed details')$$,'notification authorization deduplicates');
SELECT is((SELECT count(*)::integer FROM booking_notifications),1,'one notification per accepted offer');
UPDATE booking_notifications SET status='accepted',provider_message_id='notice090',accepted_at=now();
SELECT lives_ok($$SELECT finalize_booking_notification(id) FROM booking_notifications$$,'notification message recorded');
UPDATE conversations SET status='closed' WHERE id='30000000-0000-4000-a090-000000000001';
SELECT lives_ok($$SELECT finalize_booking_notification(id) FROM booking_notifications$$,'retry uses original closed SMS thread');
SELECT is((SELECT count(*)::integer FROM conversations WHERE channel='sms'),1,'retry creates no extra SMS conversation');
SELECT is((SELECT count(*)::integer FROM messages WHERE id IN(SELECT id FROM booking_notifications)),1,'retry creates no extra message');
SELECT is((SELECT count(*)::integer FROM goal_events),0,'booking notification is not a signup Lead');
DELETE FROM contacts WHERE id='20000000-0000-4000-a090-000000000001';
SELECT is((SELECT count(*)::integer FROM booking_notifications),0,'contact deletion removes notification details');
SELECT is((SELECT count(*)::integer FROM booking_summary_sends),0,'contact deletion removes summary send details');
SELECT * FROM finish();
ROLLBACK;
